.lane-body {
  position: relative;
  padding-left: 44px;
}

.lane-body::before {
  content: "";
  position: absolute;
  left: 32px;
  top: -15px;
  bottom: 10px;
  width: 4px;
  border-radius: 0 0 2px 2px;
  background: var(--group-color);
  opacity: 0.55;
  transition: opacity var(--transition);
}

.workspace-lane:hover .lane-body::before {
  opacity: 1;
}

.lane-title {
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
  /* Lane headers sit on the wallpaper, not a surface — use luminance-derived
     on-background text so they stay legible against any background. */
  color: var(--on-bg-muted, var(--text-secondary));
  text-shadow: var(--on-bg-shadow, none);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
  border: none;
  background: transparent;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  font-family: inherit;
  transition:
    background var(--transition),
    color var(--transition);
}

.lane-title:hover {
  color: var(--on-bg, var(--text-primary));
}

.lane-title:focus {
  outline: 2px solid var(--accent);
  color: var(--text-primary);
  text-shadow: none;
  background: var(--surface);
}

.lane-collapse-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0;
  color: var(--on-bg-muted, var(--text-secondary));
  filter: drop-shadow(var(--on-bg-shadow, 0 0 0 transparent));
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  transition:
    color var(--transition),
    background var(--transition),
    transform var(--transition);
}

.lane-collapse-btn:hover {
  background: var(--surface-hover);
---
}

.lane-color-swatch.selected {
  outline: 2px solid var(--text-primary);
  outline-offset: 2px;
}

/* Editable lane titles get a subtle hover surface to signal click-to-rename. */
.lane-title--editable:hover {
  background: var(--surface-hover);
}

.lane-tab-count {
  font-size: 11px;
  line-height: 1;
  color: var(--on-bg-muted, var(--text-secondary));
  text-shadow: var(--on-bg-shadow, none);
  opacity: 0.85;
}

.lane-delete-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--on-bg-muted, var(--text-secondary));
  text-shadow: var(--on-bg-shadow, none);
  font-size: 16px;
  line-height: 1;
  padding: 0 2px;
  margin-left: auto;
  opacity: 0;
  transition:
    opacity var(--transition),
    color var(--transition);
}

.workspace-lane:hover .lane-delete-btn {
  opacity: 1;
}

.lane-delete-btn:hover {
  color: var(--on-bg, var(--text-primary));
}

