import { activateTab } from "../utils/tabActivation.js";

export function createTabCard(tab, thumbnail) {
  const card = document.createElement("div");
  card.className = "tab-card";
  card.tabIndex = 0;
  card.dataset.tabId = tab.id;
  card.dataset.tabUrl = tab.url || "";
  card.draggable = true;

  let activeThumbnail = thumbnail;
  if (activeThumbnail) {
    const img = document.createElement("img");
    img.className = "card-thumbnail";
    img.src = activeThumbnail;
    img.alt = "";
    let loadRetries = 0;
    img.onerror = () => {
      if (loadRetries === 0) {
        loadRetries += 1;
        const retrySource = img.src;
        img.removeAttribute("src");
        setTimeout(() => {
          img.src = retrySource;
        }, 150);
        return;
      }

      img.onerror = null;
      activeThumbnail = null;
      console.warn("[Meridian] Cached thumbnail failed to load", {
        tabId: tab.id,
      });
      img.replaceWith(makeThumbnailPlaceholder(tab));
      chrome.runtime.sendMessage({
        type: "MARK_THUMBNAIL_REFRESH_NEEDED",
        tabId: tab.id,
      }).catch((error) => {
        console.warn(
          "[Meridian] Failed to mark thumbnail for refresh:",
          error.message,
        );
      });
    };
    card.appendChild(img);
  } else {
    card.appendChild(makeThumbnailPlaceholder(tab));
  }

  const info = document.createElement("div");
  info.className = "card-info";

  if (tab.favIconUrl) {
    const favicon = document.createElement("img");
    favicon.className = "card-favicon";
    favicon.src = tab.favIconUrl;
    favicon.alt = "";
    favicon.onerror = () => favicon.replaceWith(makeFaviconPlaceholder(tab.url, 14));
    info.appendChild(favicon);
  }

  const title = document.createElement("span");
  title.className = "card-title";
  title.textContent = tab.title || tab.url || "New Tab";
  info.appendChild(title);

  card.appendChild(info);

  const closeBtn = document.createElement("button");
  closeBtn.className = "card-close-btn";
  closeBtn.textContent = "×";
  closeBtn.setAttribute("aria-label", "Close tab");
  closeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    card.dispatchEvent(
      new CustomEvent("close-tab", {
        bubbles: true,
        detail: { tabId: tab.id },
      }),
    );
  });
  card.appendChild(closeBtn);

  card.addEventListener("click", () => {
    activateTab(tab.id);
  });

  card.addEventListener("keydown", (e) => {
    if (e.key === "Enter") activateTab(tab.id);
    if (e.key === "w" || e.key === "W") {
      card.dispatchEvent(
        new CustomEvent("close-tab", {
          bubbles: true,
          detail: { tabId: tab.id },
        }),
      );
    }
  });

  card.addEventListener("contextmenu", (e) => {
    e.preventDefault();
    card.dispatchEvent(
      new CustomEvent("tab-context-menu", {
        bubbles: true,
        detail: { tab, x: e.clientX, y: e.clientY },
      }),
    );
  });

  let hoverTimer = null;

  function startLightboxTimer() {
    hoverTimer = setTimeout(() => {
      hoverTimer = null;
      card.dispatchEvent(
        new CustomEvent("tab-lightbox-show", {
          bubbles: true,
          detail: {
            tab,
            thumbnail: activeThumbnail,
            rect: card.getBoundingClientRect(),
          },
        }),
      );
    }, 1000);
  }

  function cancelLightboxTimer() {
    clearTimeout(hoverTimer);
    hoverTimer = null;
  }

  card.addEventListener("mouseenter", startLightboxTimer);

  card.addEventListener("mouseleave", cancelLightboxTimer);

  closeBtn.addEventListener("mouseenter", cancelLightboxTimer);

  closeBtn.addEventListener("mouseleave", () => {
    if (card.matches(":hover")) startLightboxTimer();
  });

  card.addEventListener("dragstart", (e) => {
    clearTimeout(hoverTimer);
    hoverTimer = null;
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", String(tab.id));
    card.classList.add("dragging");
  });
  card.addEventListener("dragend", () => card.classList.remove("dragging"));

  return card;
}

function makeThumbnailPlaceholder(tab) {
  const placeholder = document.createElement("div");
  placeholder.className = "card-thumbnail-placeholder";
  placeholder.textContent = getInitial(tab.title);
  return placeholder;
}

function getInitial(title) {
  if (!title) return "?";
  return title.trim().charAt(0).toUpperCase();
}

function makeFaviconPlaceholder(url, size) {
  let letter = "?";
  try {
    letter = new URL(url).hostname.replace(/^www\./, "").charAt(0).toUpperCase() || "?";
  } catch (_) {}
  const el = document.createElement("span");
  el.className = "favicon-placeholder";
  el.style.setProperty("--favicon-size", `${size}px`);
  el.style.setProperty("--favicon-font-size", `${Math.round(size * 0.65)}px`);
  el.textContent = letter;
  return el;
}

