function evaluateFunction(source, signature) {
  const functionSource = extractFunction(source, signature).replace(
    /^export\s+/,
    "",
  );
  const name = signature.match(/function\s+(\w+)/)?.[1];
  return new Function(`${functionSource}; return ${name};`)();
}

