const target = process.argv[2];
const expression = process.argv.slice(3).join(' ');
const ws = new WebSocket(target);
let id = 0;
const pending = new Map();
ws.onmessage = ({data}) => { const m=JSON.parse(data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
function send(method, params={}) { return new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));}); }
await new Promise(r=>setTimeout(r,1000));
const out=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});
console.log(JSON.stringify(out,null,2));
ws.close();
