const [target,sourceSel,targetSel]=process.argv.slice(2);
const ws=new WebSocket(target); let id=0; const pending=new Map();
ws.onmessage=({data})=>{const m=JSON.parse(data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});
const send=(method,params={})=>new Promise(r=>{const n=++id;pending.set(n,r);ws.send(JSON.stringify({id:n,method,params}))});
const evalv=async expression=>(await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true})).result.result.value;
await evalv("'`(()=>{window.__dragEvents=[];for(const t of ['"'dragstart','dragenter','dragover','drop','dragend'])document.addEventListener(t,e=>window.__dragEvents.push({t,target:e.target.className,data:[...e.dataTransfer.types]}),true)})()"'`);
const rects=await evalv(`(()=>{const r=s=>{const x=document.querySelector(s).getBoundingClientRect();return {x:x.left+x.width/2,y:x.top+x.height/2}};return {a:r(${JSON.stringify(sourceSel)}),b:r(${JSON.stringify(targetSel)})}})()`);
const {a,b}=rects;
await send('"'Input.dispatchMouseEvent',{type:'mouseMoved',x:a.x,y:a.y});
await send('Input.dispatchMouseEvent',{type:'mousePressed',x:a.x,y:a.y,button:'left',buttons:1,clickCount:1});
for(let i=1;i<=20;i++){const f=i/20;await send('Input.dispatchMouseEvent',{type:'mouseMoved',x:a.x+(b.x-a.x)*f,y:a.y+(b.y-a.y)*f,button:'left',buttons:1});await new Promise(r=>setTimeout(r,30));}
await send('Input.dispatchMouseEvent',{type:'mouseReleased',x:b.x,y:b.y,button:'left',buttons:0,clickCount:1});
await new Promise(r=>setTimeout(r,500));
console.log(JSON.stringify(await evalv("'`(async()=>({events:window.__dragEvents,order:[...document.querySelectorAll('"'.workspace-lane')].map(x=>x.dataset.workspaceId),storage:await chrome.storage.local.get(['laneOrder','tabOrder'])}))()"'`),null,2));
ws.close();
EOF
