    async query(options) {
      queryArguments.push(options);
      return [];
    },
    async getCurrent() {
      return null;
    },
  };
  chrome.runtime = {
    getURL(path) {
      return `chrome-extension://meridian/${path}`;
    },
  };

  const build = new Function(
    "chrome",
    "document",
    "setTimeout",
    "clearTimeout",
    `
      const hasNativeGroups = false;
      let pendingRenameLaneId = null;
