.workspace-lane:hover .lane-delete-btn {
  opacity: 1;
}

.lane-delete-btn:hover {
  background: var(--surface-hover);
  color: var(--text-primary);
  mix-blend-mode: normal;
}

.tab-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 10px;
  padding: 8px;
  border-radius: var(--radius);
}

/* ---- Tab cards ---- */

.tab-card {
  background: var(--card-bg);
  -webkit-backdrop-filter: blur(var(--card-blur));
  backdrop-filter: blur(var(--card-blur));
  border-radius: var(--radius);
  box-shadow: var(--card-shadow);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  height: 150px;
  display: flex;
  flex-direction: column;
  transition:
    transform var(--transition),
    box-shadow var(--transition);
  -webkit-user-select: none;
  user-select: none;
}

.tab-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--card-shadow-hover);
}

.tab-card:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.card-thumbnail {
  width: 100%;
  flex: 1;
  min-height: 0;
  object-fit: cover;
  object-position: top;
  display: block;
  background: var(--surface-hover);
}

.card-thumbnail-placeholder {
  width: 100%;
  flex: 1;
  min-height: 0;
  background: var(--surface-hover);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-size: 24px;
  font-weight: 500;
  opacity: 0.4;
}

.card-info {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  height: 34px;
  flex-shrink: 0;
}

.card-favicon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.card-title {
  font-size: 12px;
  font-weight: 400;
  color: var(--text-primary);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.card-close-btn {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  border: none;
  cursor: pointer;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition:
    opacity var(--transition),
    background var(--transition);
  line-height: 1;
  padding: 0;
}

.tab-card:hover .card-close-btn,
.tab-card:focus-within .card-close-btn {
  opacity: 1;
}

.card-close-btn:hover {
  background: rgba(0, 0, 0, 0.75);
}

/* ---- Settings ---- */

/* Shared dropdown shell — the bookmarks/history scope view, the
   search-everything results, and settings all render into one of these.
   Anchored beneath the search pill, borderless, separated by shadow alone
   just like the pill itself. 850px is sized to the History scope's own
   ceiling: history loads at most 20 items (chrome.history.search maxResults
   in utils/browserSearch.js), and 20 rows (~36px each, incl. padding) plus
   its .search-panel-header ("Open the History page", ~50px) and list
   padding (~12px) fit at that height without scrolling — so the tallest
   legitimate popup content just fits, instead of an arbitrary round number.*/
.search-popup {
  card.addEventListener("mouseleave", cancelLightboxTimer);

  closeBtn.addEventListener("mouseenter", cancelLightboxTimer);

  closeBtn.addEventListener("mouseleave", () => {
    if (card.matches(":hover")) startLightboxTimer();
  });

  card.addEventListener("dragstart", (e) => {
    clearTimeout(hoverTimer);
    hoverTimer = null;
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", String(tab.id));
    card.classList.add("dragging");
  });
  card.addEventListener("dragend", () => card.classList.remove("dragging"));

  return card;
}

function makeThumbnailPlaceholder(tab) {
  const placeholder = document.createElement("div");
  placeholder.className = "card-thumbnail-placeholder";
  placeholder.textContent = getInitial(tab.title);
  return placeholder;
}
