    await Promise.all([
      chrome.tabs.query(
        showTabsFromAllWindows ? {} : { currentWindow: true },
      ),
      chromeGroupsPromise,
      getAllThumbnails(),
      chrome.tabs.getCurrent(),
      getWorkspaceData(),
      chrome.storage.local.get(["collapsedLanes", "tabOrder", "laneOrder"]),
    ]);
