    currentProvider = provider;
    chrome.storage.sync.set({ searchProvider: provider.id });
    api.onProviderChange?.(provider);
  }

  function notifyQuery() {
    api.onSelectionReset?.();
    api.onBrowserQuery?.(input.value.trim() || null, scope);
  }

