    scope = next;
    wrapper.dataset.scope = scope;
    // The magnifier stays the submit control across all scopes; only the
    // placeholder signals the active mode.
    input.placeholder = SCOPE_PLACEHOLDERS[scope] ?? SCOPE_PLACEHOLDERS.all;
