    getProvider: () => currentProvider,
    getProviders: () => PROVIDERS.slice(),
    setProvider: (id) => {
      const p = PROVIDERS.find((x) => x.id === id);
      if (p) updateProvider(p);
    },
    clearSearch: () => {
      input.value = "";
      updateClearBtn();
      notifyQuery();
