        `Could not load ${next === "history" ? "history" : "bookmark"} results.`,
      );
      return;
    }

    if (seq !== scopeSeq) return;
    render();
    popup.open();
  }

  async function setQuery(next) {
    selection.reset();
    query = next || "";
    if (!isOpen()) return;
    if (scope === "history") {
      const fresh = await fetchHistory(query);
      if (fresh) render();
    } else {
      render();
    }
  }

